// 21-11-2026 17:50 · Germán: filtros «Amor, Amistad, Trabajo, Familia, Salud y Bienestar» («Pareja» pasa a «Amor»). En Amor se suman
// «La otra persona es» (Mujer, Hombre, Prefiero no decir), «Tu situación (amor)» y «Nuestro vínculo»; en Trabajo, «Tu meta» (Entrevista
// laboral, Desarrollo profesional, Ascenso, Trabajo en equipo, Emprender). Se integra la DEMO: lectura enfocada por tema y la estrella
// «Tus 6 números» (1 a 22 con su arcano, textos propios) de cada persona, más los números del vínculo. Todo lo anterior se mantiene.
function horoscopoCompat(cinco) {   // cinco: la edición también trae los botones del año y del chino
  let boton = false, puesto = false;
  return {
    cabeza: { element(e) { e.append(HC_CSS, { html: true }); } },
    vista: { element(e) {
      if (boton) return; boton = true;
      e.setAttribute("class", `${e.getAttribute("class") || ""} ${cinco ? "cn-cinco" : "cn-tres"}`.trim());
      e.append('<button type="button" class="moneda horo-btn" data-v="compat" aria-pressed="false" aria-controls="horoCompat" data-no-tr><span class="mn"><span class="ha-l-es">Compatibilidad</span><span class="ha-l-en" lang="en">Compatibility</span></span></button>', { html: true });
    } },
    signos: { element(e) { if (puesto) return; puesto = true; e.after(HC_PANEL, { html: true }); } },
    cuerpo: { element(e) { e.append(HC_JS, { html: true }); } },
  };
}
